  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": [
        "C19"
      ],
      "claim": "Verapamil's strongest absolute oral bioavailability record in healthy volunteers vs IV is 27%, above the 20% threshold; other absolute values for this molecule and for sulpiride/levosulpiride fall in the 23-35% range, supporting high."
    },
    {
      "card_ids": [
        "C08"
      ],
      "claim": "Clomipramine's absolute bioavailability in nine healthy volunteers vs IV is 0.482 (48.2%), above threshold; clomipramine, tramadol, venlafaxine, pethidine, codeine, and bevantolol all have strongest ordinary-condition F values of about 40-70%, supporting high."
    },
    {
      "card_ids": [
        "C73"
      ],
      "claim": "Tramadol's absolute oral bioavailability in humans is 70% of IV exposure, clearly above threshold; this is representative of the uniformly high F values across the supplied evidence molecules."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": [],
  "decision_summary": "All 10 evidence molecules, with assay-transfer scores of 0.75-0.84, have strongest absolute or ordinary-condition oral bioavailability values above the 20% threshold (approximately 23-70%), supporting a high prediction. Some threshold-adjacent and qualitative low records introduce minor uncertainty but do not overturn the consistent positive direction.",
  "evidence_gaps": [
    "Some verapamil records (C77, C24, C07) report F below 20%, but the strongest absolute ordinary-condition record and most absolute values support high; threshold-adjacent variability remains.",
    "Sulpiride/levosulpiride records use qualitative 'low/poor' language despite numeric values of 23-35%, so the language may reflect relative expectations rather than the F>=20 threshold.",
    "Record C58 under pethidine reports morphine data, a provenance conflict; it was discounted."
  ],
  "new_evidence_assessment": [],
